// block: 64 uints is 256 bytes and there was no room for a 65th.
#define SEQ_PAST    pc.lowRank
#define SEQ_HIST    pc.injOff
#define SEQ_SRC     pc.loOff
#define ATTN_IDXRAW pc.loOff

