// into the GEMM's A layout.
func (g *HeadGPU) Upload(x []float32, rows int) error {
	if rows <= 0 || rows > g.tokens {
		return fmt.Errorf("llm: %d rows, the head arena is built for %d", rows, g.tokens)
	}
	if len(x) != rows*g.nEmbd {
